815	  test('hideBagOnMobile absent/false emits no bag-visibility rule at all — matches Home (never shows the bag) and Wishlist (shows it on every breakpoint)', () => {
816	    const style = ZimmProductCardRecipe.baseStyle({});
817	    const root = style.root as Record<string, unknown>;
818	    expect(root[BAG_KEY]).toBeUndefined();
819	    // [DESKTOP_QUERY] itself is always present (mirrors [HOVER_CAPABLE_QUERY]'s own unconditional
820	    // presence, asserted with the same `?? {}` fallback elsewhere in this file) — it's the BAG_KEY
821	    // entry inside it that must be absent when nothing needs a desktop reveal.
822	    const desktopBlock = (root[DESKTOP_QUERY] ?? {}) as Record<string, unknown>;
823	    expect(desktopBlock[BAG_KEY]).toBeUndefined();
824	  });
825	
826	  /**
827	   * Regression test for a real bug this exact combination caused: `sizeSelectorUnavailable` and
828	   * `hideBagOnMobile` used to each spread their own separate `[DESKTOP_QUERY]` object into `root`
829	   * — a plain object spread doesn't deep-merge two spreads sharing a key, so whichever one came
830	   * last silently overwrote the other's `[DESKTOP_QUERY]` value entirely. Confirmed for real in a
831	   * live browser: an unavailable PLP card's price stayed `display: none` at desktop width even
832	   * though `window.matchMedia('(min-width: 48em)').matches` correctly reported `true` — every
833	   * existing jsdom test still passed at the time, because none of them set BOTH flags at once,
834	   * which is exactly the shape a real unavailable PLP card produces (PLP's own
835	   * `hideBagOnMobile: true` combined with `sizeSelectorUnavailable: true` once it's out of stock).
836	   * This test passes that exact realistic combination and checks BOTH rules survive together in
837	   * the one shared `[DESKTOP_QUERY]` block.
838	   */
839	  test('sizeSelectorUnavailable and hideBagOnMobile together (the real unavailable-PLP shape) both survive in the same shared [DESKTOP_QUERY] block', () => {
840	    const style = ZimmProductCardRecipe.baseStyle({ sizeSelectorUnavailable: true, hideBagOnMobile: true });
841	    const root = style.root as Record<string, unknown>;
842	    const desktopBlock = root[DESKTOP_QUERY] as Record<string, unknown>;
843	    expect((desktopBlock[PRICE_KEY] as Record<string, unknown>).display).toBe('block');
844	    expect((desktopBlock[BAG_KEY] as Record<string, unknown>).display).toBe('flex');
845	  });
846	});
847	
848	/**
849	 * Fix C — DOM-level proof, same reasoning as Fix 1's own block below: an object-shape assertion
850	 * proves this recipe's `sizeSelectorUnavailable` key looks right in isolation, but not that a real
851	 * `[data-card-slot="sizeChips"]` element composed under the real generated root class actually
852	 * resolves to `display: none` once Emotion's cascade runs for real. Composes the real root recipe
853	 * (unavailable-PLP shape) with a bare marker div for the size-chips slot, through the real
854	 * (unmocked) `chakra` factory, and reads the jsdom-resolved value back via `getComputedStyle`.
855	 */
856	describe('ZimmProductCard — Fix C: size-chip wrapper is genuinely hidden when unavailable, not just un-revealed', () => {
857	  test('a real [data-card-slot="sizeChips"] element, composed under the real unavailable-PLP root recipe, resolves to display:none', () => {
858	    const rootStyle = ZimmProductCardRecipe.baseStyle({
859	      hoverHidesPrice: false,
860	      hoverRevealsPrice: false,
861	      hoverRevealsSizeSelector: false,
862	      sizeSelectorUnavailable: true,
863	    }).root;
864	
865	    const { container } = render(
866	      <chakra.div __css={rootStyle}>
867	        <div data-card-slot="content">
868	          <div data-card-slot="sizeChips">size chips</div>
869	        </div>
870	      </chakra.div>,
871	    );
872	
873	    const sizeChips = container.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`) as HTMLElement;
874	    expect(window.getComputedStyle(sizeChips).display).toBe('none');

