    ['plp', false, { hoverHidesPrice: true, hoverRevealsSizeSelector: true, sizeSelectorUnavailable: false }],
    ['plp', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: true }],
    ['wishlist', false, { hoverHidesPrice: true, hoverRevealsSizeSelector: true, sizeSelectorUnavailable: false }],
    ['wishlist', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: true }],
  ] as const)(
