test('carousel (arrows) has no reveal of its own at this recipe level — stays clipped unconditionally, even inside HOVER_CAPABLE_QUERY; indicatorWrapper is unaffected by the fix', () => {
  const style = ZimmProductCardMediaRecipe.baseStyle();

  // Touch / non-hover-capable pointers (outside the media query): indicator visible, arrows
  // clipped. Fix J (SFCC-236): `carousel`'s own unconditional hidden state was `display: 'none'`
  // — converted to `clipPath: 'inset(50%)'` (see zimmProductCard.css.ts docblock point 6's own
  // Fix J note) so the arrows stay in the DOM/tab order/accessibility tree even while clipped.
  // `display` is no longer set by this part at all — the organism's own `&:hover`/
  // `&:has(:focus-visible)` reveal rules assert `display: 'flex'` explicitly instead (needed for
  // this part's own `justifyContent`/`alignItems`, which this recipe alone can no longer supply
  // unconditionally without also making the arrows a flex row while still hidden/clipped).
  expect(style.indicatorWrapper.display).toBe('block');
  expect((style.carousel as Record<string, unknown>).display).toBeUndefined();
  expect(style.carousel.clipPath).toBe('inset(50%)');

  // Hover-capable pointers: indicatorWrapper still hides itself via its own
  // `[HOVER_CAPABLE_QUERY]` key (unchanged by this fix) — but `carousel` no longer has a
  // `[HOVER_CAPABLE_QUERY]` key AT ALL. Regression guard: if that key ever reappears here with
  // an unconditional `display: 'flex'`, the permanent-visibility bug is back.
  const carousel = style.carousel as Record<string, unknown>;
  const indicatorWrapper = style.indicatorWrapper as Record<string, unknown>;
  expect(carousel[HOVER_CAPABLE_QUERY]).toBeUndefined();
  const indicatorHoverBlock = indicatorWrapper[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
  expect(indicatorHoverBlock.display).toBe('none');
});

