332	  test("badge and close share the same fixed height, so their centred content lands on the same vertical line — regression guard: padding-only sizing on badge previously grew it to 64px against close's fixed 48px, landing badge text 9px below the close icon", () => {
333	    const style = ZimmProductCardMediaRecipe.baseStyle();
