359	describe('ZimmProductCardMedia — currentIndex re-clamps when the images gallery shrinks (Fix 3 regression)', () => {
360	  test('navigating to the last of 3 images then shrinking to 2 wraps correctly on the very next click', async () => {
361	    const user = userEvent.setup();
362	    const utils = wrap(
363	      <ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />,
364	    );
365	
366	    const next = screen.getByRole('button', { name: 'Next image' });
367	    await user.click(next); // 0 -> 1
368	    await user.click(next); // 1 -> 2 (last of 3)
369	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
370	
371	    // A colour-variant swap while the card stays mounted: the SAME instance re-renders with a
372	    // shorter images array.
373	    const SHRUNK_GALLERY = GALLERY.slice(0, 2);
374	    utils.rerender(
375	      <IntlProvider locale="en" defaultLocale="en">
376	        <ZimmProductCardMedia primaryImage={PRIMARY} images={SHRUNK_GALLERY} swapOnHover={false} showControls />
377	      </IntlProvider>,
